input.content:
[
  {
    "qa_id": "qa-006",
    "question": "バックエンドの web 向け仕様は？",
    "answer": "Python の ASGI/WSGI ベース REST API。/todos の CRUD と完了操作、/health。層は router / service / repository の 3 層。",
    "ops": [
      {"action": "confirm", "category": "backend", "platform": "web", "serves_goals": ["G2", "G3"]}
    ]
  },
  {
    "qa_id": "qa-007",
    "question": "フロントエンドの web 向け仕様は？",
    "answer": "専用フロントエンドを実装しない。動作確認は OpenAPI 定義と HTTP クライアント (curl 等) で行う。",
    "ops": [
      {"action": "confirm", "category": "frontend", "platform": "web", "serves_goals": ["G4"]}
    ]
  },
  {
    "qa_id": "qa-008",
    "question": "保守運用管理の web 向け仕様は？",
    "answer": "構造化ログを標準出力へ、/health で稼働確認、バックアップ/復旧手順を README 化。監視の外部送信は行わない。",
    "ops": [
      {"action": "confirm", "category": "maintenance-ops", "platform": "web", "serves_goals": ["G3", "G4"]}
    ]
  }
]

